ALTER TABLE TIPIMOVIMENTO ADD FKSTATOISTANZA VARCHAR2(2);
COMMENT ON COLUMN TIPIMOVIMENTO.FKSTATOISTANZA IS 'Se impostato allora in fase di inserimento di un movimento (non in update e non in elaborazione) verrà modificato lo stato dell''istanza con quello selezionato. Se il movimento viene cancellato lo stato dell''istanza non cambierà e non tornerà allo stato precedente'; 
ALTER TABLE TIPIMOVIMENTO ADD CONSTRAINT FK_TIPIMOV_STATIISTANZA FOREIGN KEY (IDCOMUNE,SOFTWARE,FKSTATOISTANZA) REFERENCES STATIISTANZA(IDCOMUNE,SOFTWARE,CODICESTATO);

CREATE TABLE ISTANZEPROCURE(ID NUMBER(10,0) NOT NULL,IDCOMUNE VARCHAR2(6) NOT NULL,CODICEISTANZA NUMBER(6,0),FK_ANAG_PROC NUMBER(6,0),FK_ANAG_PROC_STORICO NUMBER(6,0),FK_ANAG_RAPP NUMBER(6,0),FK_ANAG_RAPP_STORICO NUMBER(6,0),CODICEOGGETTOPROCURA NUMBER(10,0),STC_ID_ALLEGATO VARCHAR2(200 CHAR),STC_ID_DOCUMENTO VARCHAR2(200 CHAR));

ALTER TABLE ISTANZEPROCURE ADD CONSTRAINT PK_ISTANZEPROCURE PRIMARY KEY (IDCOMUNE, ID);
ALTER TABLE ISTANZEPROCURE ADD CONSTRAINT FK_ISTPROC_ISTANZE FOREIGN KEY (IDCOMUNE, CODICEISTANZA) REFERENCES ISTANZE(IDCOMUNE, CODICEISTANZA);
ALTER TABLE ISTANZEPROCURE ADD CONSTRAINT FK_ISTPROC_ANPROC FOREIGN KEY (IDCOMUNE, FK_ANAG_PROC) REFERENCES ANAGRAFE(IDCOMUNE, CODICEANAGRAFE);
ALTER TABLE ISTANZEPROCURE ADD CONSTRAINT FK_ISTPROC_ANPROCST FOREIGN KEY (IDCOMUNE, FK_ANAG_PROC_STORICO) REFERENCES ANAGRAFESTORICO(IDCOMUNE, ID);
ALTER TABLE ISTANZEPROCURE ADD CONSTRAINT FK_ISTPROC_ANRAP FOREIGN KEY (IDCOMUNE, FK_ANAG_RAPP) REFERENCES ANAGRAFE(IDCOMUNE, CODICEANAGRAFE);
ALTER TABLE ISTANZEPROCURE ADD CONSTRAINT FK_ISTPROC_ANRAPST FOREIGN KEY (IDCOMUNE, FK_ANAG_RAPP_STORICO) REFERENCES ANAGRAFESTORICO(IDCOMUNE, ID);
ALTER TABLE ISTANZEPROCURE ADD CONSTRAINT FK_ISTPROC_OGGETTI FOREIGN KEY (IDCOMUNE, CODICEOGGETTOPROCURA) REFERENCES OGGETTI(IDCOMUNE, CODICEOGGETTO);

CREATE OR REPLACE FORCE VIEW VW_ISTANZE_OPE_RUOLI (IDCOMUNE, IDRUOLO, CODICERESPONSABILE, CODICEISTANZA) AS SELECT RR.IDCOMUNE,RR.IDRUOLO,RR.CODICERESPONSABILE,IR.CODICEISTANZA FROM RESPONSABILIRUOLI RR INNER JOIN ISTANZERUOLI IR on rr.idcomune =ir.idcomune and rr.idruolo = ir.idruolo inner join ruoli r ON r.idcomune=ir.idcomune and r.id =ir.idruolo AND (r.readonly=0 OR (r.flag_gestmovimenti=1 OR r.flag_disgestmovamm =1));

ALTER TABLE INVENTARIOPROCEDIMENTIONERI ADD NOTE VARCHAR2(500);
ALTER TABLE ALBEROPROC_ONERI ADD NOTE VARCHAR2(500);


COMMENT ON COLUMN INVENTARIOPROCEDIMENTIONERI.NOTE IS 'LE NOTE VERRANNO VISUALIZZATE DURANTE LA PRESENTAZIONE DELLA DOMANDA ON-LINE AL PASSAGGIO RELATIVO AL RIEPILOGO ONERI';
COMMENT ON COLUMN ALBEROPROC_ONERI.NOTE IS 'LE NOTE VERRANNO VISUALIZZATE DURANTE LA PRESENTAZIONE DELLA DOMANDA ON-LINE AL PASSAGGIO RELATIVO AL RIEPILOGO ONERI';

CREATE OR REPLACE VIEW vw_listapratiche AS SELECT istanze.codicecomune,istanze.idcomune, istanze.software AS software,software.descrizionelunga AS descsoftware,istanze.codiceistanza AS idpratica,istanze.numeroistanza AS numeropratica, TO_CHAR(istanze.data,'DD/MM/YYYY') AS datapresentazione, TO_CHAR(istanze.data,'YYYY') AS annopresentazione, TO_CHAR(istanze.data,'MM') AS mesepresentazione, istanze.numeroprotocollo, TO_CHAR(istanze.dataprotocollo,'DD/MM/YYYY') AS dataprotocollo, istanze.codiceinterventoproc AS codiceintervento, vw_alberoproc.sc_descrizione AS descrizioneintervento, tipiprocedure.codiceprocedura, tipiprocedure.procedura, istanze.lavori AS oggetto, UPPER(istanze.lavori) AS oggettou, istanze.chiusura AS codstatopratica, stato AS statopratica, responsabili.responsabile, responsabili.telefonolavoro AS responsabile_telefono, NVL(stradario.codviario,stradario.codicestradario) AS pr_codviario, stradario.prefisso || ' ' || stradario.descrizione AS pr_indirizzo, istanzestradario.CODICECIVICO AS pr_codcivico, istanze.civico AS pr_civico, istanze.codicearea AS codicezonizzazione, aree.denominazione AS zonizzazione, anagrafe.codiceanagrafe AS CodiceRichiedente, NVL(upper(anagrafe.codicefiscale), '') AS codicefiscale, NVL(anagrafe.partitaiva, '') AS partitaiva, anagrafe.nominativo || ' ' || anagrafe.nome AS nominativo, anagrafe.indirizzo, anagrafe.cap, anagrafe.citta AS localita, comuneresidenza.comune AS citta, comuneresidenza.provincia, tipisoggetto.tiposoggetto AS tiporapporto, catasto.descrizione AS tipocatasto, istanzemappali.foglio, istanzemappali.particella, istanzemappali.sub, tecnico.codiceanagrafe AS tec_codice, tecnico.nominativo || ' ' || tecnico.nome AS tec_nominativo, NVL(upper(tecnico.codicefiscale), '') AS tec_codicefiscale, NVL(tecnico.partitaiva, '') AS tec_partitaiva, azienda.codiceanagrafe AS az_codice , azienda.nominativo || ' ' || azienda.nome AS az_nominativo, NVL(upper(azienda.codicefiscale), '') AS az_codicefiscale, NVL(azienda.partitaiva, '') AS az_partitaiva, istruttori.responsabile AS istruttore, istruttori.telefonolavoro AS istruttore_telefono, operatori.responsabile AS operatore, operatori.telefonolavoro AS operatore_telefono FROM istanze join software ON software.codice = istanze.software join anagrafe ON anagrafe.idcomune = istanze.idcomune AND anagrafe.codiceanagrafe = istanze.codicerichiedente join statiistanza ON statiistanza.idcomune = istanze.idcomune AND statiistanza.software = istanze.software AND statiistanza.codicestato = istanze.chiusura join vw_alberoproc ON vw_alberoproc.idcomune = istanze.idcomune AND vw_alberoproc.sc_id = istanze.codiceinterventoproc left outer join anagrafe tecnico ON tecnico.idcomune = istanze.idcomune AND tecnico.codiceanagrafe = istanze.codiceprofessionista left outer join anagrafe azienda ON istanze.idcomune = azienda.idcomune AND istanze.codicetitolarelegale = azienda.codiceanagrafe left outer join istanzestradario ON istanze.idcomune = istanzestradario.idcomune AND istanze.codiceistanza = istanzestradario.codiceistanza AND 1 = istanzestradario.primario left outer join stradario ON stradario.idcomune = istanzestradario.idcomune AND stradario.codicestradario = istanzestradario.codicestradario left outer join istanzemappali ON istanze.idcomune = istanzemappali.idcomune AND istanze.codiceistanza = istanzemappali.fkcodiceistanza AND 1 = istanzemappali.primario left outer join responsabili ON istanze.idcomune = responsabili.idcomune AND istanze.codiceresponsabileproc = responsabili.codiceresponsabile left outer join comuni comuneresidenza ON anagrafe.comuneresidenza = comuneresidenza.codicecomune left outer join tipisoggetto ON istanze.idcomune = tipisoggetto.idcomune AND istanze.fkcodicesoggetto = tipisoggetto.codicetiposoggetto left outer join aree ON istanze.idcomune = aree.idcomune AND istanze.codicearea = aree.codicearea left outer join catasto ON istanzemappali.codicecatasto = catasto.codice left outer join tipiprocedure ON istanze.idcomune = tipiprocedure.idcomune AND istanze.codiceprocedura = tipiprocedure.codiceprocedura left outer join responsabili istruttori ON istanze.idcomune = istruttori.idcomune AND istanze.codiceistruttore = istruttori.codiceresponsabile left outer join responsabili operatori ON operatori.idcomune = istanze.idcomune AND operatori.codiceresponsabile = istanze.codiceresponsabile;

CREATE TABLE RESPONSABILI_TM_SCA (IDCOMUNE VARCHAR2(6) NOT NULL,CODICERESPONSABILE NUMBER(4,0) NOT NULL,TIPOMOVIMENTO VARCHAR2(8) NOT NULL);
ALTER TABLE RESPONSABILI_TM_SCA  ADD CONSTRAINT PK_RESP_TM_SCA PRIMARY KEY (IDCOMUNE,CODICERESPONSABILE,TIPOMOVIMENTO);
ALTER TABLE RESPONSABILI_TM_SCA ADD CONSTRAINT FK_RESPTMSCA_RESP FOREIGN KEY(IDCOMUNE,CODICERESPONSABILE) REFERENCES RESPONSABILI(IDCOMUNE,CODICERESPONSABILE);
ALTER TABLE RESPONSABILI_TM_SCA ADD CONSTRAINT FK_RESPTMSCA_TIPIMOV FOREIGN KEY(IDCOMUNE,TIPOMOVIMENTO) REFERENCES TIPIMOVIMENTO(IDCOMUNE,TIPOMOVIMENTO);

COMMENT ON TABLE RESPONSABILI_TM_SCA IS 'Permette di configurare a livello di operatore su quali tipimovimenti limitare la ricerca dei movimenti "Da eseguire"';

CREATE TABLE RESPONSABILI_TM_AVV (IDCOMUNE VARCHAR2(6) NOT NULL,CODICERESPONSABILE NUMBER(4,0) NOT NULL,TIPOMOVIMENTO VARCHAR2(8) NOT NULL);

COMMENT ON TABLE RESPONSABILI_TM_AVV IS 'Permette di configurare a livello di operatore su quali tipimovimenti limitare la ricerca dei movimenti "Da Visionare"';
  
ALTER TABLE RESPONSABILI_TM_AVV  ADD CONSTRAINT PK_RESP_TM_AVV PRIMARY KEY (IDCOMUNE,CODICERESPONSABILE,TIPOMOVIMENTO);
ALTER TABLE RESPONSABILI_TM_AVV ADD CONSTRAINT FK_RESPTMAVV_RESP FOREIGN KEY(IDCOMUNE,CODICERESPONSABILE) REFERENCES RESPONSABILI(IDCOMUNE,CODICERESPONSABILE);
ALTER TABLE RESPONSABILI_TM_AVV ADD CONSTRAINT FK_RESPTMAVV_TIPIMOV FOREIGN KEY(IDCOMUNE,TIPOMOVIMENTO) REFERENCES TIPIMOVIMENTO(IDCOMUNE,TIPOMOVIMENTO);

ALTER TABLE TIPIMOVIMENTO ADD FLAG_DISDAVISIONARE NUMBER(1,0);
COMMENT ON COLUMN TIPIMOVIMENTO.FLAG_DISDAVISIONARE IS 'INIBISCE IN FASE DI INSERIMENTO DA SISTEMI ESTERNI (STC) IL SETTAGGIO A 1 DI MOVIMENTI.FLAGDALEGGERE DURANTE UNA NOTIFICA';

CREATE OR REPLACE VIEW VW_I_ATTIVITAINFORMAZIONI AS SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZEATTIVITA.CODICEISTANZA, ISTANZEATTIVITA.CODICEATTIVITA, ISTANZEATTIVITA.METRIQ, ISTANZEATTIVITA.NOTE, ISTANZEATTIVITA.IDCOMUNE, ISTANZEATTIVITA.SOFTWARE, ISTANZEATTIVITA.IDATTIVITA, SETTORI.CODICESETTORE, SETTORI.SETTORE FROM I_ATTIVITA, ISTANZEATTIVITA, ATTIVITA, SETTORI WHERE SETTORI.IDCOMUNE = ATTIVITA.IDCOMUNE AND SETTORI.CODICESETTORE = ATTIVITA.CODICESETTORE AND ATTIVITA.IDCOMUNE = ISTANZEATTIVITA.IDCOMUNE AND ATTIVITA.CODICEISTAT = ISTANZEATTIVITA.CODICEATTIVITA AND ISTANZEATTIVITA.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZEATTIVITA.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA;

ALTER table ISTANZE ADD CONSTRAINT FK_ISTANZE_ATTIVITA FOREIGN KEY (IDCOMUNE,FK_IDI_ATTIVITA) REFERENCES I_ATTIVITA (IDCOMUNE, ID);

ALTER TABLE STATIISTANZA ADD CONSTRAINT FK_STATI_COMPORTAMENTO FOREIGN KEY (FKCODCOMPORTAMENTO) REFERENCES STATICOMPORTAMENTO (CODCOMPORTAMENTO);
CREATE INDEX IDX_STATIISTANZA_001 ON STATIISTANZA (FKCODCOMPORTAMENTO);

ALTER TABLE ISTANZE MODIFY NUMEROISTANZA VARCHAR2(60 CHAR);
ALTER TABLE DOMANDESTC MODIFY NUMEROISTANZA VARCHAR2(60 CHAR);
ALTER TABLE DOMANDESTC MODIFY ID_DOMANDAMITT VARCHAR2(60 CHAR);

ALTER TABLE ISTANZE ADD DOMICILIO_ELETTRONICO VARCHAR2(320 CHAR);
COMMENT ON COLUMN ISTANZE.DOMICILIO_ELETTRONICO IS 'E'' IL DOMICILIO ELETTRONICO DI RIFERIMENTO (TIPICAMENTE PEC) PER RICEVERE COMUNICAZIONI IN MERITO ALLA PRATICA DA PARTE DEI RICHIEDENTI/PROFESSIONISTI.';

CREATE OR REPLACE VIEW VW_I_ATTIVITAENDO AS SELECT I_ATTIVITA.IDCOMUNE, I_ATTIVITA.ID as I_IDATTIVITA, ISTANZEPROCEDIMENTI.CODICEISTANZA, TIPIFAMIGLIEENDO.CODICE AS CODICEFAMIGLIA, TIPIFAMIGLIEENDO.TIPO AS FAMIGLIA, TIPIENDO.CODICE AS CODICETIPO, TIPIENDO.TIPO, ISTANZEPROCEDIMENTI.CODICEINVENTARIO, INVENTARIOPROCEDIMENTI.PROCEDIMENTO, ISTANZEPROCEDIMENTI.PERPROVVEDIMENTO, ISTANZEPROCEDIMENTI.ACQUISITO, ISTANZEPROCEDIMENTI.DATAATTIVAZIONE, ISTANZEPROCEDIMENTI.NOTE FROM I_ATTIVITA, ISTANZE, ISTANZEPROCEDIMENTI, INVENTARIOPROCEDIMENTI, TIPIENDO, TIPIFAMIGLIEENDO WHERE TIPIFAMIGLIEENDO.IDCOMUNE(+) = TIPIENDO.IDCOMUNE AND TIPIFAMIGLIEENDO.CODICE(+) = TIPIENDO.CODICEFAMIGLIAENDO AND TIPIENDO.IDCOMUNE(+) = INVENTARIOPROCEDIMENTI.IDCOMUNE AND TIPIENDO.CODICE(+) = INVENTARIOPROCEDIMENTI.CODICETIPO AND INVENTARIOPROCEDIMENTI.IDCOMUNE = ISTANZEPROCEDIMENTI.IDCOMUNE AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = ISTANZEPROCEDIMENTI.CODICEINVENTARIO AND ISTANZEPROCEDIMENTI.IDCOMUNE = ISTANZE.IDCOMUNE AND ISTANZEPROCEDIMENTI.CODICEISTANZA = ISTANZE.CODICEISTANZA AND ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE AND ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID;

ALTER TABLE RESPONSABILI ADD FLAG_CANCELLAISTANZE NUMBER(1,0);
COMMENT ON COLUMN RESPONSABILI.FLAG_CANCELLAISTANZE IS 'ABILITA L''OPERATORE A CANCELLARE LE ISTANZE E TUTTE LE INFORMAZIONI COLLEGATE';
ALTER TABLE RESPONSABILI ADD FLAG_CANCELLADOCUMENTISTC NUMBER(1,0);
COMMENT ON COLUMN RESPONSABILI.FLAG_CANCELLADOCUMENTISTC IS 'ABILITA L''OPERATORE A CANCELLARE I DOCUMENTI DELLE ISTANZE PROVENIENTI DA SISTEMI ESTERNI (STC) E NEL CASO DEI MOVIMENTI ANCHE LE EMAIL INVIATE';

ALTER TABLE TIPIMOV_STC_MAPPING ADD (FLAG_INVIASCHEDEISTANZA NUMERIC(1,0));
COMMENT ON COLUMN TIPIMOV_STC_MAPPING.FLAG_INVIASCHEDEISTANZA IS 'Se selezionato nella maschera di notifica attivita'' risulteranno selezionate tutte le schede dinamiche dell''istanza indipendentemente da quanto specificato in TIPI_MOV_STC_MODELLI';


CREATE OR REPLACE VIEW VW_ISTANZECONCESSIONIPREC_TMP AS SELECT IDCOMUNE, CONC_ID, MAX(DATA_STORICO) AS DATA_STORICO FROM VW_ISTANZECONCESSIONILISTA WHERE PROGRESSIVO < 99999999 GROUP BY IDCOMUNE, CONC_ID;

CREATE OR REPLACE VIEW VW_ISTANZECONCESSIONIPREC AS 
SELECT  
  VW_ISTANZECONCESSIONILISTA.IDCOMUNE, VW_ISTANZECONCESSIONILISTA.CONC_ID, VW_ISTANZECONCESSIONILISTA.DATA_STORICO, MAX(PROGRESSIVO) AS PROGRESSIVO 
FROM  
  VW_ISTANZECONCESSIONILISTA, VW_ISTANZECONCESSIONIPREC_TMP 
WHERE  
 VW_ISTANZECONCESSIONILISTA.IDCOMUNE = VW_ISTANZECONCESSIONIPREC_TMP.IDCOMUNE AND 
 VW_ISTANZECONCESSIONILISTA.CONC_ID = VW_ISTANZECONCESSIONIPREC_TMP.CONC_ID AND 
 VW_ISTANZECONCESSIONILISTA.DATA_STORICO = VW_ISTANZECONCESSIONIPREC_TMP.DATA_STORICO AND 
 VW_ISTANZECONCESSIONILISTA.PROGRESSIVO < 99999999  
GROUP BY  
 VW_ISTANZECONCESSIONILISTA.IDCOMUNE, VW_ISTANZECONCESSIONILISTA.CONC_ID, VW_ISTANZECONCESSIONILISTA.DATA_STORICO;

CREATE OR REPLACE VIEW VW_ISTANZECONCESSIONILISTA AS 

SELECT 99999999 AS PROGRESSIVO, AUTORIZZAZIONI.AUTORIZRESPONSABILE AS CONC_AUTORIZRESPONSABILE, AUTORIZZAZIONI.IDCOMUNE, AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE, NVL(AUTORIZZAZIONI.DATA_CESSAZIONE,TO_DATE('31/12/9999','DD/MM/YYYY')) AS DATA_STORICO, ISTANZE.SOFTWARE, ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA, ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA, ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE, ISTANZE.CODICETITOLARELEGALE AS IST_CODICETITOLARELEGALE, AUTORIZZAZIONI.ID AS CONC_ID, AUTORIZZAZIONI.AUTORIZNUMERO AS CONC_NUMERO, AUTORIZZAZIONI.AUTORIZDATA AS CONC_DATARILASCIO, AUTORIZZAZIONI.AUTORIZDATA AS DATARILASCIO, AUTORIZZAZIONI.DATASCADENZA AS CONC_DATASCADENZA, AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO, CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO, AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA, AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA, AUTORIZZAZIONI.FLAG_ATTIVA AS CONC_ATTIVA, AUTORIZZAZIONI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE, TITOLARE.NOMINATIVO || ' ' || TITOLARE.NOME AS CONC_TITOLARE, TITOLARE.CODICEFISCALE AS CONC_TIT_CF, TITOLARE.PARTITAIVA AS CONC_TIT_PIVA, TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE, AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO, AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA, AUT_COLLEGATA.AUTORIZDATA, AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO, TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO, IST_RICHIEDENTE.NOMINATIVO || ' ' || IST_RICHIEDENTE.NOME AS IST_NOMINATIVO, IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE, IST_AZIENDA.NOMINATIVO || ' ' || IST_AZIENDA.NOME AS IST_NOMINATIVOAZIENDA, IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE, IST_AZIENDA.CODICEFISCALE AS IST_AZI_CODICEFISCALE, IST_AZIENDA.PARTITAIVA AS IST_AZI_PARTITAIVA, IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE, IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA, CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE, AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO, CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO, AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO, MERCATI.DESCRIZIONE AS CONC_MERCATO, MERCATI.ATTIVO AS MERC_ATTIVO, AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO, MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO, MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA, MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA, MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE, MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO, POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO, AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO, MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO, MERCATI_USO.PESO AS PESO_MERCATO, MERCATI_USO.FKCODICEUSO AS MERC_IDUSO, MERCATI_D.FKCODICESTRADARIO AS CONC_POS_CODICESTRADARIO FROM AUTORIZZAZIONI, AUTORIZZAZIONI_CONCESSIONI, AUTORIZZAZIONI AUT_COLLEGATA, CONCESSIONITIPI, TIPOLOGIAREGISTRI, ANAGRAFE TITOLARE, CONCESSIONICAUSALI CAUS_ATTUALE, CONCESSIONICAUSALI CAUS_STORICO, ISTANZE, ANAGRAFE IST_RICHIEDENTE, MERCATI, MERCATI_D, POSTEGGITIPOSPAZIO, MERCATI_USO, ANAGRAFE IST_AZIENDA WHERE AUTORIZZAZIONI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND AUT_COLLEGATA.IDCOMUNE(+) = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUT_COLLEGATA.ID(+) = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TIPOLOGIAREGISTRI.IDCOMUNE(+) = AUTORIZZAZIONI.IDCOMUNE AND TIPOLOGIAREGISTRI.TR_ID(+) = AUTORIZZAZIONI.FKIDREGISTRO AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AND CAUS_STORICO.IDCOMUNE(+) = AUTORIZZAZIONI.IDCOMUNE AND CAUS_STORICO.CODICECAUSALE(+) = AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE AND ISTANZE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND ISTANZE.CODICEISTANZA = AUTORIZZAZIONI.FKIDISTANZA AND IST_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND IST_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND MERCATI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI.CODICEMERCATO = AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AND MERCATI_D.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_D.IDPOSTEGGIO = AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AND POSTEGGITIPOSPAZIO.IDCOMUNE(+) = MERCATI_D.IDCOMUNE AND POSTEGGITIPOSPAZIO.CODICE(+) = MERCATI_D.FKCODICETIPOSPAZIO AND MERCATI_USO.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_USO.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AND IST_AZIENDA.IDCOMUNE(+) = ISTANZE.IDCOMUNE AND IST_AZIENDA.CODICEANAGRAFE(+) = ISTANZE.CODICETITOLARELEGALE 

UNION 

SELECT AUTORIZZAZIONI_SUBENTRI.ID AS PROGRESSIVO, AUTORIZZAZIONI_SUBENTRI.AUTORIZRESPONSABILE AS CONC_AUTORIZRESPONSABILE, AUTORIZZAZIONI_SUBENTRI.IDCOMUNE, AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE, AUTORIZZAZIONI_SUBENTRI.DATA_CESSAZIONE AS DATA_STORICO, ISTANZE.SOFTWARE, ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA, ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA, ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE, ISTANZE.CODICETITOLARELEGALE AS IST_CODICETITOLARELEGALE, AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE AS CONC_ID, AUTORIZZAZIONI_SUBENTRI.AUTORIZNUMERO AS CONC_NUMERO, AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS CONC_DATARILASCIO, AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS DATARILASCIO, AUTORIZZAZIONI_SUBENTRI.DATASCADENZA AS CONC_DATASCADENZA, AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO, CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO, AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA, AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA, 0 AS CONC_ATTIVA,AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE,TITOLARE.NOMINATIVO || ' ' || TITOLARE.NOME AS CONC_TITOLARE, TITOLARE.CODICEFISCALE AS CONC_TIT_CF,TITOLARE.PARTITAIVA AS CONC_TIT_PIVA, TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE, AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO, AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA, AUT_COLLEGATA.AUTORIZDATA,AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO, TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO,IST_RICHIEDENTE.NOMINATIVO || ' ' || IST_RICHIEDENTE.NOME AS IST_NOMINATIVO, IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE, IST_AZIENDA.NOMINATIVO || ' ' || IST_AZIENDA.NOME AS IST_NOMINATIVOAZIENDA, IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE, IST_AZIENDA.CODICEFISCALE AS IST_AZI_CODICEFISCALE, IST_AZIENDA.PARTITAIVA AS IST_AZI_PARTITAIVA, IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE,IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA, CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE, AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO, CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO, AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO, MERCATI.DESCRIZIONE AS CONC_MERCATO,MERCATI.ATTIVO AS MERC_ATTIVO,AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO, MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO, MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA,MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA,MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE, MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO,POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO,AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO, MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO,MERCATI_USO.PESO AS PESO_MERCATO, MERCATI_USO.FKCODICEUSO AS MERC_IDUSO, MERCATI_D.FKCODICESTRADARIO AS CONC_POS_CODICESTRADARIO FROM AUTORIZZAZIONI_SUBENTRI,AUTORIZZAZIONI_CONCESSIONI, AUTORIZZAZIONI AUT_COLLEGATA, CONCESSIONITIPI, TIPOLOGIAREGISTRI,ANAGRAFE TITOLARE,CONCESSIONICAUSALI CAUS_ATTUALE, CONCESSIONICAUSALI CAUS_STORICO, ISTANZE, ANAGRAFE IST_RICHIEDENTE,MERCATI,MERCATI_D,POSTEGGITIPOSPAZIO, MERCATI_USO,ANAGRAFE IST_AZIENDA WHERE AUTORIZZAZIONI_SUBENTRI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.FK_IDAUT_ATTUALE = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND AUT_COLLEGATA.IDCOMUNE(+) = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUT_COLLEGATA.ID(+) = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA AND CONCESSIONITIPI.TIPOCONCESSIONE = AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TIPOLOGIAREGISTRI.IDCOMUNE(+) = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND TIPOLOGIAREGISTRI.TR_ID(+) = AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO AND TITOLARE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE = AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE = AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE AND CAUS_STORICO.IDCOMUNE(+) = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND CAUS_STORICO.CODICECAUSALE(+) = AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE AND ISTANZE.IDCOMUNE = AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND ISTANZE.CODICEISTANZA = AUTORIZZAZIONI_SUBENTRI.FKIDISTANZA AND IST_RICHIEDENTE.IDCOMUNE = ISTANZE.IDCOMUNE AND IST_RICHIEDENTE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND MERCATI.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI.CODICEMERCATO = AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AND MERCATI_D.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_D.IDPOSTEGGIO = AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AND POSTEGGITIPOSPAZIO.IDCOMUNE(+) = MERCATI_D.IDCOMUNE AND POSTEGGITIPOSPAZIO.CODICE(+) = MERCATI_D.FKCODICETIPOSPAZIO AND MERCATI_USO.IDCOMUNE = AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_USO.ID = AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AND IST_AZIENDA.IDCOMUNE(+) = ISTANZE.IDCOMUNE AND IST_AZIENDA.CODICEANAGRAFE(+) = ISTANZE.CODICETITOLARELEGALE;

ALTER TABLE FO_ARCONFIGURAZIONE  ADD (FKID_SCHEDA_EC NUMBER(10, 0) );
COMMENT ON COLUMN FO_ARCONFIGURAZIONE.FKID_SCHEDA_EC IS 'Scheda dinamica da compilare nel caso che il richiedente sia cittadino extracomunitario';

ALTER TABLE FO_ARCONFIGURAZIONE  ADD (FLG_SCHEDA_EC_RICHIEDEFIRMA NUMBER(1, 0) );
COMMENT ON COLUMN FO_ARCONFIGURAZIONE.FLG_SCHEDA_EC_RICHIEDEFIRMA IS 'Indica se FO_ARCONFIGURAZIONE.FKID_SCHEDA_EC debba essere firmata nel frontoffice per poter essere presentata';

ALTER TABLE FO_ARCONFIGURAZIONE ADD CONSTRAINT FK_ARCONF_DYN2_MOD_T FOREIGN KEY (IDCOMUNE,FKID_SCHEDA_EC) REFERENCES DYN2_MODELLIT  (IDCOMUNE, ID);

ALTER TABLE CITTADINANZA ADD (FLG_PAESE_COMUNITARIO NUMBER(1, 0) );
COMMENT ON COLUMN CITTADINANZA.FLG_PAESE_COMUNITARIO IS 'Se 1 indica che il paese appartiene alla CEE';

ALTER TABLE ALBEROPROC ADD CODICEOGGETTO_WORKFLOW NUMBER(10);
ALTER TABLE ALBEROPROC ADD CONSTRAINT FK_ALBERO_PROC_OGG_WORKFLOW FOREIGN KEY (IDCOMUNE, CODICEOGGETTO_WORKFLOW) REFERENCES OGGETTI (   IDCOMUNE,CODICEOGGETTO);
COMMENT ON COLUMN ALBEROPROC.CODICEOGGETTO_WORKFLOW IS 'CODICE OGGETTO DA UTILIZZARE NEL WORKFLOW DELL''AREA RISERVATA QUANDO SI SELEZIONA L''INTERVENTO';

ALTER TABLE DOMANDESTC MODIFY RICHIEDENTE NULL;

ALTER TABLE AMMINISTRAZIONI MODIFY STC_IDENTE VARCHAR2(20 CHAR);
ALTER TABLE DOMANDESTC MODIFY ID_ENTEMITT VARCHAR2(20 CHAR);

CREATE TABLE TIPICAUSALIONINTERESSI (IDCOMUNE VARCHAR2(6) NOT NULL, ID NUMBER(8) NOT NULL, FK_IDTIPOCAUSALE NUMBER(10) NOT NULL, GGRITARDOPAGAMENTO NUMBER(4) NOT NULL, PERCENTUALE NUMBER(8, 5) NOT NULL);
ALTER TABLE TIPICAUSALIONINTERESSI ADD CONSTRAINT TIPICAUSALIONINTERESSI_PK PRIMARY KEY(IDCOMUNE,ID);
ALTER TABLE TIPICAUSALIONINTERESSI ADD CONSTRAINT FK_TIPICAUSALIINTERESSI_001 FOREIGN KEY(IDCOMUNE, FK_IDTIPOCAUSALE) REFERENCES TIPICAUSALIONERI(IDCOMUNE, CO_ID);
COMMENT ON COLUMN TIPICAUSALIONINTERESSI.FK_IDTIPOCAUSALE IS 'FK verso TIPICAUSALIONERI.CO_ID';
COMMENT ON COLUMN TIPICAUSALIONINTERESSI.GGRITARDOPAGAMENTO IS 'E'' il limite massimo di giorni in cui può ricadere il ritardo per essere applicata la rispettiva percentuale';
COMMENT ON COLUMN TIPICAUSALIONINTERESSI.PERCENTUALE IS 'E'' la percentuale che verrà applicata qualora la scadenza rientri nella rispettiva fascia';

ALTER TABLE TIPICAUSALIONERI ADD FLG_TIPICAUSALIINTERESSI NUMBER(1);
ALTER TABLE TIPICAUSALIONERI ADD FK_TIPICAUSALIINTERESSI NUMBER(8);
ALTER TABLE TIPICAUSALIONERI ADD CONSTRAINT FK_TIPICAUSON_INTERESSI FOREIGN KEY(IDCOMUNE, FK_TIPICAUSALIINTERESSI) REFERENCES TIPICAUSALIONERI(IDCOMUNE, CO_ID);
COMMENT ON COLUMN TIPICAUSALIONERI.FLG_TIPICAUSALIINTERESSI IS '1: Identifica che la causale è una causale di interesse ( con tanto di configurazione ); 0 o NULL: è una causale standard. Applicativamente non può essere impostato a 1 quando TIPICAUSALIONERI.FK_TIPICAUSALIINTERESSI <> null';
COMMENT ON COLUMN TIPICAUSALIONERI.FK_TIPICAUSALIINTERESSI IS 'FK con TIPICAUSALIONERI.CO_ID; indica se la causale ha una causale di interesse collegata. Applicativamente non può essere valorizzato quando TIPICAUSALIONERI.FLG_TIPICAUSALIINTERESSI = 1';
 

ALTER TABLE ISTANZEONERI ADD FK_IDPADRE NUMBER(10);
ALTER TABLE ISTANZEONERI ADD CONSTRAINT FK_ISTONERI_ISTONERIPADRE FOREIGN KEY(IDCOMUNE, FK_IDPADRE) REFERENCES ISTANZEONERI(IDCOMUNE, ID);
COMMENT ON COLUMN ISTANZEONERI.FK_IDPADRE IS 'FK con ISTANZEONERI.ID; indica la riga di ISTANZEONERI padre da cui è stata generata la riga di ISTANZEONERI figlia';

CREATE OR REPLACE VIEW VW_LISTAAUTORIZZAZIONI AS SELECT AUTORIZZAZIONI.IDCOMUNE, AUTORIZZAZIONI.FKIDISTANZA AS CODICEISTANZA, ISTANZE.NUMEROISTANZA, AUTORIZZAZIONI.AUTORIZNUMERO AS NUMEROAUTORIZZAZIONE, AUTORIZZAZIONI.AUTORIZDATA AS DATAAUTORIZZAZIONE, COMUNI.COMUNE AS COMUNEAUTORIZZAZIONE, TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS REGISTRO, ANAGRAFE.CODICEANAGRAFE, ANAGRAFE.NOMINATIVO || ' ' || ANAGRAFE.NOME AS ANAGRAFICA, ISTANZE.LAVORI AS OGGETTOISTANZA, STRADARIO.CODICESTRADARIO AS LOCALIZZAZIONECODICEVIA, STRADARIO.PREFISSO || ' ' || STRADARIO.DESCRIZIONE AS LOCALIZZAZIONE, ISTANZESTRADARIO.CIVICO AS LOCALIZZAZIONECIVICO FROM AUTORIZZAZIONI LEFT JOIN ISTANZE ON AUTORIZZAZIONI.IDCOMUNE=ISTANZE.IDCOMUNE AND AUTORIZZAZIONI.FKIDISTANZA=ISTANZE.CODICEISTANZA LEFT JOIN ISTANZESTRADARIO ON ISTANZESTRADARIO.IDCOMUNE=ISTANZE.IDCOMUNE AND ISTANZESTRADARIO.CODICEISTANZA=ISTANZE.CODICEISTANZA LEFT JOIN STRADARIO ON ISTANZESTRADARIO.IDCOMUNE=STRADARIO.IDCOMUNE AND ISTANZESTRADARIO.CODICESTRADARIO=STRADARIO.CODICESTRADARIO LEFT JOIN TIPOLOGIAREGISTRI ON TIPOLOGIAREGISTRI.IDCOMUNE=AUTORIZZAZIONI.IDCOMUNE AND TIPOLOGIAREGISTRI.TR_ID=AUTORIZZAZIONI.FKIDREGISTRO, ANAGRAFE, COMUNI WHERE ANAGRAFE.IDCOMUNE = AUTORIZZAZIONI.IDCOMUNE AND ANAGRAFE.CODICEANAGRAFE = AUTORIZZAZIONI.FK_CODICEANAGRAFE AND COMUNI.CODICECOMUNE=AUTORIZZAZIONI.AUTORIZCOMUNE AND (ISTANZESTRADARIO.PRIMARIO=1 OR ISTANZESTRADARIO.PRIMARIO IS NULL);